    --bg-color: #0a0a0a;
    --surface-color: #1a1a1a;
    --primary-color: #ffffff;
    --secondary-color: #a0a0a0;
    --accent-color: #ffffff;
    --text-main: #e0e0e0;
    --text-muted: #909090;
    --border-color: #707070;
    --focus-ring: #4da3ff;

    --container-width: 1200px;
    --section-spacing: 5rem;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: var(--bg-color);
    color: var(--text-main);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    line-height: 1.6;
}

/* Accessibility */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.sr-only:focus {
    position: static;
    width: auto;
    height: auto;
    padding: 1rem;
    background: var(--surface-color);
    color: var(--primary-color);
    clip: auto;
    white-space: normal;
    z-index: 1000;
}

:focus-visible {
    outline: 2px solid var(--focus-ring);
    outline-offset: 4px;
}

/* Layout */
.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 1.5rem;
}

/* Header */
.site-header {
    background: rgba(10, 10, 10, 0.95);
    border-bottom: 1px solid var(--border-color);
    padding: 1rem 0;
    position: sticky;
    top: 0;
    z-index: 100;
    backdrop-filter: blur(8px);
}

.header-inner {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo-text {
    font-weight: 800;
    letter-spacing: 0.2rem;
    font-size: 1.5rem;
    color: var(--primary-color);
}

.logo {
    text-decoration: none;
}

.main-nav ul {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.main-nav a {
    color: var(--text-main);
    text-decoration: none;
    font-weight: 500;
    transition: color 0.2s;
}

.main-nav a:hover {
    color: var(--primary-color);
}

.header-actions {
    display: flex;
    gap: 1rem;
}

.icon-btn {
    background: none;
    border: none;
    color: var(--text-main);
    cursor: pointer;
    padding: 0.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: color 0.2s;
}

.icon-btn:hover {
    color: var(--primary-color);
}

/* Hero */
.hero {
    padding: 8rem 0;
    text-align: center;
    background: linear-gradient(rgba(10, 10, 10, 0.7), rgba(10, 10, 10, 0.7)),
                url('https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1600&q=80');
    background-size: cover;
    background-position: center;
}

.hero-content {
    max-width: 600px;
    margin: 0 auto;
}

.hero h1 {
    font-size: 3.5rem;
    margin-bottom: 1.5rem;
    line-height: 1.1;
    color: var(--primary-color);
}

.hero p {
    font-size: 1.25rem;
    color: var(--text-muted);
    margin-bottom: 2.5rem;
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 1rem 2rem;
    border-radius: 2px;
    text-decoration: none;
    font-weight: 600;
    transition: all 0.2s;
    cursor: pointer;
    border: 1px solid transparent;
}

.btn-primary {
    background: var(--primary-color);
    color: var(--bg-color);
}

.btn-primary:hover {
    background: #e0e0e0;
}

.btn-outline {
    background: transparent;
    border-color: var(--primary-color);
    color: var(--primary-color);
}

.btn-outline:hover {
    background: rgba(255, 255, 255, 0.1);
}

.btn-text:hover {
    text-decoration: underline;
}

.logo:focus-visible {
    outline: 2px solid var(--focus-ring);
    outline-offset: 4px;
}

/* Featured Products */
.featured-products {
    padding: var(--section-spacing) 0;
}

.featured-products h2 {
    margin-bottom: 3rem;
    font-size: 2rem;
    text-align: center;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 2rem;
}

.product-card {
    background: var(--surface-color);
    border: 1px solid var(--border-color);
    padding: 1rem;
    display: flex;
    flex-direction: column;
}

.product-image {
    width: 100%;
    aspect-ratio: 1;
    object-fit: cover;
    margin-bottom: 1rem;
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
}

.product-info h3 a {
    color: var(--primary-color);
    text-decoration: none;
}

.product-price {
    color: var(--text-muted);
    font-weight: 600;
    margin-bottom: 1rem;
}

.add-to-cart {
    margin-top: auto;
    width: 100%;
    padding: 0.75rem;
    background: transparent;
    border: 1px solid var(--border-color);
    color: var(--text-main);
    cursor: pointer;
    transition: all 0.2s;
}

.add-to-cart:hover {
    border-color: var(--primary-color);
    background: rgba(255, 255, 255, 0.05);
}

/* Deals */
.deals-section {
    padding: var(--section-spacing) 0;
}

.deals-banner {
    background: #1a1a1a;
    padding: 4rem;
    border: 1px solid var(--border-color);
    text-align: center;
}

.deals-content h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.deals-content p {
    font-size: 1.25rem;
    color: var(--text-muted);
    margin-bottom: 2rem;
}

/* Editorial */
.editorial-content {
    padding: var(--section-spacing) 0;
}

.editorial-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

.editorial-image img {
    width: 100%;
    border-radius: 4px;
}

.editorial-text h2 {
    font-size: 2.5rem;
    margin-bottom: 1.5rem;
}

.editorial-text p {
    margin-bottom: 1.5rem;
    color: var(--text-muted);
}

/* Footer */
.site-footer {
    padding: 4rem 0 2rem;
    border-top: 1px solid var(--border-color);
    margin-top: var(--section-spacing);
}

.footer-grid {
    display: grid;
    grid-template-columns: 1fr 2fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-nav {
    display: flex;
    gap: 4rem;
}

.nav-group h3 {
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.1rem;
    margin-bottom: 1.5rem;
    color: var(--primary-color);
}

.nav-group ul {
    list-style: none;
}

.nav-group li {
    margin-bottom: 0.75rem;
}

.nav-group a {
    color: var(--text-muted);
    text-decoration: none;
    transition: color 0.2s;
}

.nav-group a:hover {
    color: var(--primary-color);
}

.footer-bottom {
    padding-top: 2rem;
    border-top: 1px solid var(--border-color);
    text-align: center;
    color: var(--text-muted);
    font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 768px) {
    .editorial-grid {
        grid-template-columns: 1fr;
        gap: 2rem;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }

    .hero h1 {
        font-size: 2.5rem;
    }
}

@media (prefers-reduced-motion: reduce) {
    * {
        animation: none !important;
        transition: none !important;
    }
}
